-- Rebuild Medina Book 3 lesson 2 strictly from the supplied Arabic sharh.
-- Canonical page references: Sharkh_Medinskiy_3.pdf, PDF pages 18-21.
-- Verbatim source_text was mechanically extracted from the matching DOC edition and checked against the PDF.
-- Two DOC control-character Qur'anic runs were transcribed literally from the visible PDF scan.

begin;

do $migration$
declare
  old_rule_count integer;
  new_rule_count integer;
  source_count integer;
begin
  select count(*) into old_rule_count
  from public.rules
  where course_name = 'Мединский курс (Том 3)' and lesson_number = '2';

  if old_rule_count <> 8 then
    raise exception 'Expected 8 generated Book 3 lesson 2 rules, found %', old_rule_count;
  end if;

  delete from public.rule_sections
  where rule_id in (select id from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '2');

  delete from public.rule_sources
  where rule_id in (select id from public.rules where course_name = 'Мединский курс (Том 3)' and lesson_number = '2');

  delete from public.rules
  where course_name = 'Мединский курс (Том 3)' and lesson_number = '2';

  insert into public.rules (course_name, lesson_number, title, content, sort_order, rule_kind, summary, rule_ar) values
('Мединский курс (Том 3)', '2', 'وَاوُ الْحَالِ (вау состояния)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar"><span class="ar-tone-particle">وَاوُ الْحَالِ</span> يَصِحُّ وُقُوعُ <span class="ar-tone-particle">إِذْ</span> الظَّرْفِيَّةِ مَوْقِعَهَا، وَالْجُمْلَةُ بَعْدَهَا فِي مَحَلِّ نَصْبٍ حَالًا.</span><p class="rule-study-text">Смысл этой вау можно передать через <span class="ar-inline ar-tone-particle" dir="rtl" lang="ar">إِذْ</span> «когда, в то время как». Введённое ею предложение целиком является обстоятельством состояния.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Какие предложения она вводит</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">الْجُمْلَةُ الاِسْمِيَّةُ</span><span class="rule-term-ru">именное предложение</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar ar-tone-verb" dir="rtl" lang="ar">الْجُمْلَةُ الْفِعْلِيَّةُ الَّتِي فِعْلُهَا مَاضٍ</span><span class="rule-term-ru">глагольное предложение, если его глагол стоит в прошедшем времени</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Грамматический статус</span><p class="rule-study-text"><span class="ar-inline ar-tone-particle" dir="rtl" lang="ar">وَاوُ الْحَالِ: حَرْفٌ مَبْنِيٌّ عَلَى الْفَتْحِ لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ وَلَا عَمَلَ لَهُ.</span></p><p class="rule-study-text">Это неизменяемая частица, построенная на фатхе; синтаксического места и управления у неё нет.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Все примеры шарха</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">جُمْلَةُ الْحَالِ</span><span class="rule-table-ru">предложение состояния</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">русский смысл</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">جَاءَ الْمُدَرِّسُ وَهُوَ يَضْحَكُ.</span><span class="rule-table-ru">Преподаватель пришёл, смеясь.</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">هُوَ يَضْحَكُ</span><span class="rule-table-ru">он смеётся</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">فِي مَحَلِّ نَصْبٍ حَالًا</span><span class="rule-table-ru">в позиции обстоятельства состояния</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">حَجَجْتُ وَأَنَا صَغِيرٌ.</span><span class="rule-table-ru">Я совершил хадж, когда был маленьким.</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَنَا صَغِيرٌ</span><span class="rule-table-ru">я маленький</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">فِي مَحَلِّ نَصْبٍ حَالًا</span><span class="rule-table-ru">в позиции обстоятельства состояния</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">دَخَلْتُ الْمَسْجِدَ وَالنَّاسُ يُصَلُّونَ.</span><span class="rule-table-ru">Я вошёл в мечеть, когда люди молились.</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">النَّاسُ يُصَلُّونَ</span><span class="rule-table-ru">люди молятся</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">فِي مَحَلِّ نَصْبٍ حَالًا</span><span class="rule-table-ru">в позиции обстоятельства состояния</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">وَصَلْتُ مَكَّةَ وَقَدْ غَرَبَتِ الشَّمْسُ.</span><span class="rule-table-ru">Я прибыл в Мекку, когда солнце уже зашло.</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">قَدْ غَرَبَتِ الشَّمْسُ</span><span class="rule-table-ru">солнце уже зашло</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">فِي مَحَلِّ نَصْبٍ حَالًا</span><span class="rule-table-ru">в позиции обстоятельства состояния</span></td></tr></tbody></table></div></div></div>', 1, 'rule', 'Вау состояния вводит именное предложение либо глагольное предложение с прошедшим глаголом; всё последующее предложение занимает место обстоятельства состояния.', 'وَاوُ الْحَالِ حَرْفٌ مَبْنِيٌّ عَلَى الْفَتْحِ لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ وَلَا عَمَلَ لَهُ. يَصِحُّ وُقُوعُ إِذْ الظَّرْفِيَّةِ مَوْقِعَهَا، وَتَدْخُلُ عَلَى الْجُمْلَةِ الاِسْمِيَّةِ، أَوْ عَلَى الْجُمْلَةِ الْفِعْلِيَّةِ الَّتِي فِعْلُهَا مَاضٍ، وَتَكُونُ الْجُمْلَةُ بَعْدَهَا فِي مَحَلِّ نَصْبٍ حَالًا.'),
('Мединский курс (Том 3)', '2', 'لَعَلَّ (частица надежды и опасения)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar"><span class="ar-tone-particle">لَعَلَّ</span> تَنْصِبُ الاِسْمَ وَتَرْفَعُ الْخَبَرَ، وَتُفِيدُ <span class="ar-tone-structure">التَّرَجِّيَ</span> أَوِ <span class="ar-tone-structure">الْإِشْفَاقَ</span>.</span><p class="rule-study-text">Это изменяющая частица из сестёр <span class="ar-inline ar-tone-particle" dir="rtl" lang="ar">إِنَّ</span>: её имя стоит в <span class="ar-inline ar-tone-nasb" dir="rtl" lang="ar">نَصْبٍ</span>, а сказуемое — в <span class="ar-inline ar-tone-raf" dir="rtl" lang="ar">رَفْعٍ</span>.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Два значения</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">значение</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">شَرْحُهُ</span><span class="rule-table-ru">объяснение автора</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّرَجِّي</span><span class="rule-table-ru">надежда</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَرْجُو أَنْ يَكُونَ بِخَيْرٍ.</span><span class="rule-table-ru">Надеюсь, что с ним всё хорошо.</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">لَعَلَّهُ بِخَيْرٍ.</span><span class="rule-table-ru">Надеюсь, с ним всё хорошо.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْإِشْفَاقُ</span><span class="rule-table-ru">опасение</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَخْشَى أَنْ يَكُونَ مَرِيضًا.</span><span class="rule-table-ru">Опасаюсь, что он болен.</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">لَعَلَّهُ مَرِيضٌ.</span><span class="rule-table-ru">Опасаюсь, что он болен.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Остальные примеры шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-predicate"><span class="rule-example-ar ar-tone-predicate" dir="rtl" lang="ar">لَعَلَّكَ نَاجِحٌ.</span><span class="rule-example-ru">Надеюсь, ты преуспел.</span></div><div class="rule-example-card rule-term-predicate"><span class="rule-example-ar ar-tone-predicate" dir="rtl" lang="ar">لَعَلَّكَ رَاسِبٌ.</span><span class="rule-example-ru">Опасаюсь, что ты не сдал.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">لَعَلِّي لَا أَحُجُّ بَعْدَ عَامِي هَذَا.</span><span class="rule-example-ru">Возможно, после этого моего года я больше не совершу хадж.</span></div></div></div></div>', 2, 'rule', 'Частица لَعَلَّ управляет как одна из сестёр إِنَّ и выражает либо надежду, либо опасение.', 'لَعَلَّ حَرْفٌ نَاسِخٌ مِنْ أَخَوَاتِ إِنَّ، يَنْصِبُ الاِسْمَ وَيَرْفَعُ الْخَبَرَ، وَلَهُ مَعْنَيَانِ: التَّرَجِّي وَالْإِشْفَاقُ.'),
('Мединский курс (Том 3)', '2', 'إِلَيْكُمْ (имя повелительного глагола «возьмите»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar"><span class="ar-tone-verb">إِلَيْكُمْ</span> اسْمُ فِعْلِ أَمْرٍ بِمَعْنَى <span class="ar-tone-verb">خُذُوا</span>.</span><p class="rule-study-text">Имя глагола замещает глагол по времени, значению и управлению.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Форма и значение</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar ar-tone-verb" dir="rtl" lang="ar">إِلَيْكُمْ</span><span class="rule-term-ru">возьмите; вот вам</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar ar-tone-verb" dir="rtl" lang="ar">خُذُوا</span><span class="rule-term-ru">возьмите — глагол, который оно замещает</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar ar-tone-verb" dir="rtl" lang="ar">اسْمُ فِعْلِ أَمْرٍ</span><span class="rule-term-ru">имя повелительного глагола</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">مَبْنِيٌّ عَلَى السُّكُونِ</span><span class="rule-term-ru">неизменяемо и построено на сукуне</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Пример шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">إِلَيْكُمْ أَمْثِلَةً أُخْرَى.</span><span class="rule-example-ru">Возьмите другие примеры.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Полный разбор</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْكَلِمَةُ</span><span class="rule-table-ru">слово</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِعْرَابُهَا</span><span class="rule-table-ru">грамматический разбор</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّرْجَمَةُ</span><span class="rule-table-ru">русское объяснение</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">إِلَيْكُمْ</span><span class="rule-table-ru">возьмите</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اسْمُ فِعْلِ أَمْرٍ مَبْنِيٌّ عَلَى السُّكُونِ.</span><span class="rule-table-ru">имя повелительного глагола, построенное на сукуне</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يَنُوبُ عَنْ خُذُوا.</span><span class="rule-table-ru">замещает «возьмите»</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">أَمْثِلَةً</span><span class="rule-table-ru">примеры</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مَفْعُولٌ بِهِ مَنْصُوبٌ، وَعَلَامَةُ نَصْبِهِ الْفَتْحَةُ الظَّاهِرَةُ.</span><span class="rule-table-ru">прямое дополнение в винительном состоянии; признак — явная фатха</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مَفْعُولٌ بِهِ</span><span class="rule-table-ru">прямое дополнение</span></td></tr></tbody></table></div></div></div>', 3, 'rule', 'إِلَيْكُمْ — имя повелительного глагола со значением خُذُوا; оно выполняет его управление и ставит прямое дополнение в винительное состояние.', 'إِلَيْكُمْ اسْمُ فِعْلِ أَمْرٍ مَبْنِيٌّ عَلَى السُّكُونِ، يَنُوبُ عَنْ خُذُوا فِي زَمَنِهِ وَمَعْنَاهُ وَعَمَلِهِ، فَيَنْصِبُ الْمَفْعُولَ بِهِ.'),
('Мединский курс (Том 3)', '2', 'أَشْيَاءُ (слово «вещи»: запрет склонения с танвином)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar"><span class="ar-tone-structure">أَشْيَاءُ</span> مَمْنُوعٌ مِنَ الصَّرْفِ لِأَلِفِ التَّأْنِيثِ الْمَمْدُودَةِ.</span><p class="rule-study-text">Слово «вещи» относится к именам, которые не принимают танвин.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Объяснение формы</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْعُنْصُرُ</span><span class="rule-table-ru">элемент</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">بَيَانُهُ</span><span class="rule-table-ru">данные шарха</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">русский смысл</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْكَلِمَةُ</span><span class="rule-table-ru">слово</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَشْيَاءُ</span><span class="rule-table-ru">вещи</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَمْنُوعٌ مِنَ الصَّرْفِ</span><span class="rule-table-ru">не принимает танвин</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْعِلَّةُ</span><span class="rule-table-ru">причина</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَلِفُ التَّأْنِيثِ الْمَمْدُودَةُ</span><span class="rule-table-ru">удлинённый алиф женского рода</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">عِلَّةٌ وَاحِدَةٌ</span><span class="rule-table-ru">одна достаточная причина</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْأَصْلُ</span><span class="rule-table-ru">исходная форма</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَشْيِئَاءُ</span><span class="rule-table-ru">исходное строение слова</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">حُذِفَتِ الْهَمْزَةُ تَخْفِيفًا</span><span class="rule-table-ru">одна хамза удалена для облегчения</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْوَزْنُ</span><span class="rule-table-ru">морфологический вес</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَفْعِلَاءُ</span><span class="rule-table-ru">модель слова</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَغْنِيَاءُ، أَصْدِقَاءُ</span><span class="rule-table-ru">богатые; друзья</span></td></tr></tbody></table></div></div></div>', 4, 'rule', 'Слово أَشْيَاءُ запрещено от танвина из-за удлинённого алифа женского рода; шарх приводит исходную форму, вес и причину облегчения.', 'أَشْيَاءُ اسْمٌ مَمْنُوعٌ مِنَ الصَّرْفِ لِعِلَّةٍ وَاحِدَةٍ، وَهِيَ أَلِفُ التَّأْنِيثِ الْمَمْدُودَةُ. أَصْلُهُ أَشْيِئَاءُ عَلَى وَزْنِ أَفْعِلَاءُ، وَحُذِفَتْ مِنْهُ الْهَمْزَةُ تَخْفِيفًا.'),
('Мединский курс (Том 3)', '2', 'الْفِعْلُ الْمَاضِي الَّذِي يُفِيدُ الدُّعَاءَ (прошедший глагол со значением мольбы)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar">الْفِعْلُ الْمَاضِي فِي الدُّعَاءِ مَاضٍ لَفْظًا، وَلَكِنَّهُ مُسْتَقْبَلٌ مَعْنًى.</span><p class="rule-study-text">Глагол имеет форму прошедшего времени, но выражает пожелание или мольбу о будущем.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Утверждение и отрицание</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْحَالَةُ</span><span class="rule-table-ru">случай</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">русский смысл</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الدُّعَاءُ</span><span class="rule-table-ru">мольба</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">شَفَاهُ اللَّهُ.</span><span class="rule-table-ru">Да исцелит его Аллах.</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">مَاضٍ لَفْظًا، مُسْتَقْبَلٌ مَعْنًى</span><span class="rule-table-ru">прошедший по форме, будущий по смыслу</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">نَفْيُ الدُّعَاءِ</span><span class="rule-table-ru">отрицательная мольба</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">لَا شَفَاهُ اللَّهُ.</span><span class="rule-table-ru">Да не исцелит его Аллах.</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">يُنْفَى بِلَا النَّافِيَةِ</span><span class="rule-table-ru">отрицается частицей ля</span></td></tr></tbody></table></div></div></div>', 5, 'rule', 'Форма прошедшего времени может обозначать обращённую к будущему мольбу; её отрицание строится с отрицательной لَا.', 'قَدْ يَكُونُ الْفِعْلُ مَاضِيًا فِي اللَّفْظِ مُسْتَقْبَلًا فِي الْمَعْنَى إِذَا أَفَادَ الدُّعَاءَ، وَيُنْفَى هَذَا الْفِعْلُ الْمَاضِي بِلَا النَّافِيَةِ.'),
('Мединский курс (Том 3)', '2', 'مِنْ الزَّائِدَةُ (добавочный предлог مِنْ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar"><span class="ar-tone-particle">مِنْ الزَّائِدَةُ</span> تَأْتِي بَعْدَ نَفْيٍ أَوْ نَهْيٍ أَوِ اسْتِفْهَامٍ بِـ<span class="ar-tone-particle">هَلْ</span>، وَيَكُونُ مَجْرُورُهَا نَكِرَةً.</span><p class="rule-study-text">Смысл <span class="ar-inline ar-tone-particle" dir="rtl" lang="ar">مِنْ</span> в этих конструкциях — усиление высказывания и прямое распространение на весь род.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Два обязательных условия</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الشَّرْطُ</span><span class="rule-table-ru">условие</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">صُوَرُهُ</span><span class="rule-table-ru">допустимые варианты</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">شَرْحُهُ</span><span class="rule-table-ru">русское объяснение</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">أَنْ يَسْبِقَهَا نَفْيٌ أَوْ نَهْيٌ أَوِ اسْتِفْهَامٌ بِهَلْ</span><span class="rule-table-ru">перед нею стоит отрицание, запрет или вопрос с هَلْ</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">نَفْيٌ، نَهْيٌ، هَلْ</span><span class="rule-table-ru">отрицание; запрет; вопрос</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">يَسْبِقُهَا وَاحِدٌ مِنْ هَذِهِ الثَّلَاثَةِ</span><span class="rule-table-ru">перед нею стоит один из трёх названных видов</span></td></tr><tr><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">أَنْ يَكُونَ مَجْرُورُهَا نَكِرَةً</span><span class="rule-table-ru">управляемое имя должно быть неопределённым</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">رَجُلٍ، طَالِبٍ، أَحَدٍ، سُؤَالٍ</span><span class="rule-table-ru">мужчина; студент; кто-либо; вопрос</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">النَّكِرَةُ</span><span class="rule-table-ru">неопределённое имя</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Все примеры шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar ar-tone-particle" dir="rtl" lang="ar">﴿ مَا جَاءَنَا مِنْ بَشِيرٍ ﴾</span><span class="rule-example-ru">«К нам не приходил ни один вестник».</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar ar-tone-particle" dir="rtl" lang="ar">لَا تَظْلِمْ مِنْ أَحَدٍ.</span><span class="rule-example-ru">Не притесняй никого.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar ar-tone-particle" dir="rtl" lang="ar">هَلْ مِنْ رَجُلٍ عِنْدَكَ؟</span><span class="rule-example-ru">Есть ли у тебя хоть один мужчина?</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar ar-tone-particle" dir="rtl" lang="ar">مَا غَابَ مِنْ طَالِبٍ.</span><span class="rule-example-ru">Не отсутствовал ни один студент.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Значение всеобщности</span><p class="rule-study-text"><span class="ar-inline ar-tone-particle" dir="rtl" lang="ar">مَا غَابَ مِنْ طَالِبٍ.</span> означает, что не отсутствовал ни один представитель всего рода студентов. Поэтому автор формулирует: <span class="ar-inline ar-tone-particle" dir="rtl" lang="ar">مِنْ الزَّائِدَةُ تُفِيدُ النَّصَّ عَلَى الْعُمُومِ.</span></p></div><div class="rule-study-card"><span class="rule-card-kicker">Полный إِعْرَاب примера</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْكَلِمَةُ</span><span class="rule-table-ru">слово</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِعْرَابُهَا</span><span class="rule-table-ru">грамматический разбор</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الشَّرْحُ</span><span class="rule-table-ru">русское объяснение</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">مَا</span><span class="rule-table-ru">не</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">حَرْفُ نَفْيٍ مَبْنِيٌّ عَلَى السُّكُونِ لَا مَحَلَّ لَهُ مِنَ الْإِعْرَابِ.</span><span class="rule-table-ru">отрицательная частица, построенная на сукуне, без синтаксического места</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">نَفْيٌ</span><span class="rule-table-ru">отрицание</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">غَابَ</span><span class="rule-table-ru">отсутствовал</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">فِعْلٌ مَاضٍ مَبْنِيٌّ عَلَى الْفَتْحِ.</span><span class="rule-table-ru">прошедший глагол, построенный на фатхе</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">فِعْلٌ مَاضٍ</span><span class="rule-table-ru">прошедший глагол</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">مِنْ</span><span class="rule-table-ru">из; здесь добавочный предлог</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">حَرْفُ جَرٍّ زَائِدٌ مَبْنِيٌّ عَلَى السُّكُونِ.</span><span class="rule-table-ru">добавочный предлог, построенный на сукуне</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">حَرْفُ جَرٍّ زَائِدٌ</span><span class="rule-table-ru">добавочный предлог</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">طَالِبٍ</span><span class="rule-table-ru">студент</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">فَاعِلٌ مَرْفُوعٌ، وَعَلَامَةُ رَفْعِهِ الضَّمَّةُ الْمُقَدَّرَةُ، مَنَعَ مِنْ ظُهُورِهَا اشْتِغَالُ الْمَحَلِّ بِحَرَكَةِ حَرْفِ الْجَرِّ الزَّائِدِ، وَهِيَ الْكَسْرَةُ.</span><span class="rule-table-ru">исполнитель в именительном состоянии; дамма подразумевается, потому что место занято касрой добавочного предлога</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">الضَّمَّةُ مُقَدَّرَةٌ، وَالْكَسْرَةُ ظَاهِرَةٌ</span><span class="rule-table-ru">дамма подразумевается, а касра добавочного предлога произносится явно</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Какую роль сохраняет имя после مِنْ</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الدَّوْرُ</span><span class="rule-table-ru">синтаксическая роль</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْأَصْلُ</span><span class="rule-table-ru">исходная конструкция</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">فَاعِلٌ</span><span class="rule-table-ru">исполнитель</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">مَا غَابَ مِنْ طَالِبٍ.</span><span class="rule-table-ru">Не отсутствовал ни один студент.</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">كَمَا فِي الْمِثَالِ السَّابِقِ.</span><span class="rule-table-ru">Как в предыдущем примере.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مَفْعُولٌ بِهِ</span><span class="rule-table-ru">прямое дополнение</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَا تَظْلِمْ مِنْ أَحَدٍ.</span><span class="rule-table-ru">Не притесняй никого.</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">لَا تَظْلِمْ أَحَدًا.</span><span class="rule-table-ru">Не притесняй никого.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُبْتَدَأٌ</span><span class="rule-table-ru">подлежащее именного предложения</span></td><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">هَلْ مِنْ سُؤَالٍ؟</span><span class="rule-table-ru">Есть ли какой-нибудь вопрос?</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">هَلْ سُؤَالٌ عِنْدَكُمْ؟</span><span class="rule-table-ru">Есть ли у вас вопрос?</span></td></tr></tbody></table></div></div></div>', 6, 'rule', 'Добавочный предлог مِنْ употребляется после отрицания, запрета или вопроса с هَلْ перед неопределённым именем и подчёркивает всеобщность отрицания или вопроса.', 'تَكُونُ مِنْ زَائِدَةً إِذَا سَبَقَهَا نَفْيٌ أَوْ نَهْيٌ أَوِ اسْتِفْهَامٌ بِهَلْ، وَكَانَ مَجْرُورُهَا نَكِرَةً. وَتُفِيدُ التَّوْكِيدَ وَالنَّصَّ عَلَى الْعُمُومِ.'),
('Мединский курс (Том 3)', '2', 'لَدَى (обстоятельственное имя места «у, при»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar"><span class="ar-tone-structure">لَدَى</span> ظَرْفُ مَكَانٍ مُعْرَبٌ بِمَعْنَى <span class="ar-tone-structure">عِنْدَ</span>.</span><p class="rule-study-text">Это изменяемое обстоятельственное имя места со значением «у, при, возле».</p></div><div class="rule-study-card"><span class="rule-card-kicker">Форма перед местоимением</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الصِّيغَةُ</span><span class="rule-table-ru">форма</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">русский смысл</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">لَدَى</span><span class="rule-table-ru">без местоимения</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">وَجَدْتُ الْقَلَمَ لَدَى زَيْدٍ.</span><span class="rule-table-ru">Я нашёл ручку у Зейда.</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">بِمَعْنَى عِنْدَ</span><span class="rule-table-ru">со значением «у»</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">لَدَيْكَ</span><span class="rule-table-ru">с местоимением «твой»</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَاذَا لَدَيْكَ؟</span><span class="rule-table-ru">Что у тебя?</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">تُقْلَبُ الْأَلِفُ يَاءً</span><span class="rule-table-ru">алиф превращается в йа</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">لَدَيْنَا</span><span class="rule-table-ru">с местоимением «наш»</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">﴿ وَلَدَيْنَا كِتَابٌ يَنْطِقُ بِالْحَقِّ ﴾</span><span class="rule-table-ru">«И у Нас есть Книга, которая говорит истину».</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">تُقْلَبُ الْأَلِفُ يَاءً</span><span class="rule-table-ru">алиф превращается в йа</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Предложение для разбора</span><div class="rule-example-list"><div class="rule-example-card rule-term-predicate"><span class="rule-example-ar ar-tone-predicate" dir="rtl" lang="ar">لَدَيَّ قَلَمٌ.</span><span class="rule-example-ru">У меня есть ручка.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Полный إِعْرَاب</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْكَلِمَةُ</span><span class="rule-table-ru">слово</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِعْرَابُهَا</span><span class="rule-table-ru">грамматический разбор</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الشَّرْحُ</span><span class="rule-table-ru">русское объяснение</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">لَدَيَّ</span><span class="rule-table-ru">у меня</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">ظَرْفُ مَكَانٍ مَنْصُوبٌ بِفَتْحَةٍ مُقَدَّرَةٍ، مَنَعَ مِنْ ظُهُورِهَا التَّعَذُّرُ، وَهُوَ مُضَافٌ.</span><span class="rule-table-ru">обстоятельственное имя места в винительном состоянии с подразумеваемой фатхой; её проявлению мешает невозможность произношения; первая часть идафы</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">خَبَرٌ مُقَدَّمٌ</span><span class="rule-table-ru">предшествующее сказуемое</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">يَاءُ الْمُتَكَلِّمِ</span><span class="rule-table-ru">йа говорящего</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">فِي مَحَلِّ جَرٍّ مُضَافٌ إِلَيْهِ.</span><span class="rule-table-ru">занимает позицию родительного состояния как вторая часть идафы</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">ضَمِيرٌ مُتَّصِلٌ</span><span class="rule-table-ru">присоединённое местоимение</span></td></tr><tr><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">شِبْهُ الْجُمْلَةِ لَدَيَّ</span><span class="rule-table-ru">оборот «у меня»</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">فِي مَحَلِّ رَفْعٍ خَبَرٌ مُقَدَّمٌ.</span><span class="rule-table-ru">занимает позицию именительного состояния как предшествующее сказуемое</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">خَبَرٌ مُقَدَّمٌ</span><span class="rule-table-ru">предшествующее сказуемое</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">قَلَمٌ</span><span class="rule-table-ru">ручка</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">مُبْتَدَأٌ مُؤَخَّرٌ مَرْفُوعٌ، وَعَلَامَةُ رَفْعِهِ الضَّمَّةُ الظَّاهِرَةُ.</span><span class="rule-table-ru">последующее подлежащее именного предложения в именительном состоянии; признак — явная дамма</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُبْتَدَأٌ مُؤَخَّرٌ</span><span class="rule-table-ru">последующее подлежащее</span></td></tr></tbody></table></div></div></div>', 7, 'rule', 'لَدَى — изменяемое обстоятельственное имя места со значением عِنْدَ; перед присоединённым местоимением его алиф превращается в йа.', 'لَدَى ظَرْفُ مَكَانٍ مُعْرَبٌ بِمَعْنَى عِنْدَ، وَتُقْلَبُ أَلِفُهَا يَاءً عِنْدَ إِضَافَتِهِ إِلَى الضَّمِيرِ.'),
('Мединский курс (Том 3)', '2', 'الْجَمْعُ عَلَى صِيغَةِ مُنْتَهَى الْجُمُوعِ (множественное число по модели предельного множественного)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar" dir="rtl" lang="ar">صِيغَةُ مُنْتَهَى الْجُمُوعِ هِيَ نِهَايَةُ الْجَمْعِ، وَهَذِهِ الصِّيَغُ مَمْنُوعَةٌ مِنَ الصَّرْفِ.</span><p class="rule-study-text">Автор объясняет название как «предел множественного числа» и относит эти модели к запрещённым от танвина.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Названные в шархе модели</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْوَزْنُ</span><span class="rule-table-ru">морфологическая модель</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">حُكْمُهُ</span><span class="rule-table-ru">грамматический статус</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَفَاعِلُ</span><span class="rule-table-ru">модель</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَسَاجِدَ</span><span class="rule-table-ru">мечети</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَمْنُوعٌ مِنَ الصَّرْفِ</span><span class="rule-table-ru">запрещено от полного склонения</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">فَوَاعِلُ</span><span class="rule-table-ru">модель</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">خَوَاتِمَ</span><span class="rule-table-ru">кольца; печати</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَمْنُوعٌ مِنَ الصَّرْفِ</span><span class="rule-table-ru">запрещено от полного склонения</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">فَيَاعِلُ</span><span class="rule-table-ru">модель</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">صَيَارِفَ</span><span class="rule-table-ru">менялы</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَمْنُوعٌ مِنَ الصَّرْفِ</span><span class="rule-table-ru">запрещено от полного склонения</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">فَعَائِلُ</span><span class="rule-table-ru">модель</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">صَحَائِفَ</span><span class="rule-table-ru">листы; свитки</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَمْنُوعٌ مِنَ الصَّرْفِ</span><span class="rule-table-ru">запрещено от полного склонения</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَفَاعِيلُ</span><span class="rule-table-ru">модель</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَصَابِيحَ</span><span class="rule-table-ru">светильники</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَمْنُوعٌ مِنَ الصَّرْفِ</span><span class="rule-table-ru">запрещено от полного склонения</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Недостаточное имя на этой модели</span><span class="rule-main-ar ar-tone-structure" dir="rtl" lang="ar">إِذَا جَاءَ الاِسْمُ الْمَنْقُوصُ عَلَى صِيغَةِ مُنْتَهَى الْجُمُوعِ، حُذِفَتْ يَاؤُهُ رَفْعًا وَجَرًّا، وَعُوِّضَ عَنْهَا بِالتَّنْوِينِ.</span><p class="rule-study-text">Оно обрабатывается как недостаточное имя единственного числа: йа удаляется в именительном и родительном состояниях, а танвин служит компенсацией.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Три примера и полный разбор</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْكَلِمَةُ</span><span class="rule-table-ru">разбираемое слово</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">إِعْرَابُهَا</span><span class="rule-table-ru">полный разбор</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">لِلْوَاوِ مَعَانٍ كَثِيرَةٌ.</span><span class="rule-table-ru">У вау много значений.</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">مَعَانٍ</span><span class="rule-table-ru">значения</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">مُبْتَدَأٌ مَرْفُوعٌ، وَعَلَامَةُ رَفْعِهِ الضَّمَّةُ الْمُقَدَّرَةُ عَلَى الْيَاءِ الْمَحْذُوفَةِ، وَالتَّنْوِينُ عِوَضٌ عَنِ الْيَاءِ الْمَحْذُوفَةِ.</span><span class="rule-table-ru">подлежащее именного предложения в именительном состоянии; дамма подразумевается на удалённой йа, танвин заменяет эту йа</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اشْتَرَكْتُ فِي نَوَادٍ ثَقَافِيَّةٍ.</span><span class="rule-table-ru">Я участвовал в культурных клубах.</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">نَوَادٍ</span><span class="rule-table-ru">клубы</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">اسْمٌ مَجْرُورٌ بِفِي، وَعَلَامَةُ جَرِّهِ الْفَتْحَةُ الْمُقَدَّرَةُ عَلَى الْيَاءِ الْمَحْذُوفَةِ، وَالتَّنْوِينُ لِلْعِوَضِ.</span><span class="rule-table-ru">имя после предлога в родительном состоянии; фатха подразумевается на удалённой йа, танвин служит компенсацией</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">عِشْتُ لَيَالِيَ سَعِيدَةً.</span><span class="rule-table-ru">Я прожил счастливые ночи.</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">لَيَالِيَ</span><span class="rule-table-ru">ночи</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">مَفْعُولٌ بِهِ مَنْصُوبٌ، وَعَلَامَةُ نَصْبِهِ الْفَتْحَةُ الظَّاهِرَةُ.</span><span class="rule-table-ru">прямое дополнение в винительном состоянии; признак — явная фатха</span></td></tr></tbody></table></div></div></div>', 8, 'rule', 'Модели предельного множественного запрещены от танвина; если такая форма одновременно является недостаточным именем, её йа удаляется в именительном и родительном состояниях.', 'صِيَغُ مُنْتَهَى الْجُمُوعِ مَمْنُوعَةٌ مِنَ الصَّرْفِ، وَمِنْ أَوْزَانِهَا: مَفَاعِلُ، وَفَوَاعِلُ، وَفَيَاعِلُ، وَفَعَائِلُ، وَمَفَاعِيلُ. وَإِذَا جَاءَ الاِسْمُ الْمَنْقُوصُ عَلَى صِيغَةِ مُنْتَهَى الْجُمُوعِ عُومِلَ مُعَامَلَةَ الاِسْمِ الْمَنْقُوصِ الْمُفْرَدِ، فَتُحْذَفُ يَاؤُهُ رَفْعًا وَجَرًّا، وَيُنَوَّنُ تَنْوِينَ عِوَضٍ.');

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_3.pdf', 'وَاوُ الْحَالِ
واو الحال ، هي : التي يَصِحُّ وقوعُ ( إِذْ ) الظَّرْفيَّةِ مَوْقِعَهَا ، وتدخل على الجملة الاسميَّة ،
أو الجملة الفعليَّة التي فعلها ماضٍ .
واو الحال : حرفٌ مبنيٌّ على الفتح لا محلَّ له من الإعراب ، ولا عَمَلَ له .
الأمثلة :  جاء المدرسُ وهو يضحك .                  حَجَجْتُ وأنا صغيرٌ .
دخلتُ المسجدَ والنَّاسُ يصلُّونَ .             وصلتُ مَكَّةَ وقد غَرَبَتِ الشَّمْسُ .
* الجمل التي تحتها خط في محلّ نصب حال .', 18, 18, 1
from public.rules
where course_name = 'Мединский курс (Том 3)' and lesson_number = '2' and sort_order = 1;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_3.pdf', 'لَعَلَّ
لَعَلَّ : حرفٌ ناسخٌ مِن أخوات إِنَّ ينصب الاسم ، ويرفع الخبر ، وله مَعْنَيَانِ :
1- التَّرَجَّي ، نحو : لعلَّه بخيرٍ ، أي : أَرْجُو أن يكون بخير ، ونحو : لعلَّك ناجحٌ .
2- الإِشْفَاقُ ، نحو : لعلَّه مريضٌ ، أي : أَخْشَى أن يكون مريضا ، ونحو : لعلَّك رَاسِبٌ،
ومنه قوله ( : " لَعَلَّي لا أَحُجُّ بَعْدَ عَامِي هَذَا " .', 18, 18, 1
from public.rules
where course_name = 'Мединский курс (Том 3)' and lesson_number = '2' and sort_order = 2;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_3.pdf', '( إِلَيْكُمْ )
إِلَيْكُمْ : اسمُ فعلِ أمرٍ ؛ لأنه نَابَ عن الفعل ( خُذُوا ) .
عرفنا سابقاً أنّ اسم الفعل ينوب عن الفعل في زمنه ، ومعناه ، وعمله ؛ فقولنا :
إليكمْ أمثلةً أخرى ، إليكمْ : اسم فعل أمر مبني على السكون .
أمثلةً : مفعول به منصوب وعلامة نصبه الفتحة الظاهرة .', 19, 19, 1
from public.rules
where course_name = 'Мединский курс (Том 3)' and lesson_number = '2' and sort_order = 3;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_3.pdf', 'أَشْيَاءُ
أشياءُ : اسمٌ ممنوعٌ من الصَّرفِ لعلَّةٍ واحدةٍ ، هي: أنه مختوم بألف التأنيث الممدودة ، وقد حُذِفَت منه الهمزة تَخْفِيفاً؛ إذ أصله ( أَشْيِئَاءُ ) على وزن أَفْعِلاَءُ ، نحو: أغنياء ، وأصدقاء.', 19, 19, 1
from public.rules
where course_name = 'Мединский курс (Том 3)' and lesson_number = '2' and sort_order = 4;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_3.pdf', 'الفعلُ الماضِي الذي يُفيدُ الدُّعَاءَ
شَفاهُ اللهُ : شفاه فعلٌ ماضٍ لفظاً لكنّه مُسْتَقْبَلٌ في المعنى ، فهو يفيدُ الدعاء .
والفعل الماضي الذي يفيد الدعاء يُنْفَي بـ ( لا ) النافية ، نحو : لا شفاه الله .', 19, 19, 1
from public.rules
where course_name = 'Мединский курс (Том 3)' and lesson_number = '2' and sort_order = 5;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_3.pdf', 'مِنْ الزَّائِدَةُ
تكونُ مِنْ زائدةً بشرطين :
1- أَنْ يَسْبِقَها نفيٌّ ، أو نَهْيٌ ، أو استفهام بـ ( هَلْ ) .
2- أَنْ يكون مجرورُها نكرةً .
فائدتها : التَّوكيد .
الأمثلة :
قال تعالى : ﴿ مَا جَاءَنَا مِنْ بَشِيرٍ ﴾ .      لا تَظْلِمْ مِنْ أحدٍ .
هَلْ مِنْ رجلٍ عندك ؟                            ما غابَ من طالبٍ .
المعنى : معنى قولنا : ما غابَ مِنْ طالبٍ ، أي : التأكيد على عُمُوم الْحُكْم وشُمُولِه لكلّ فَرْدٍ مِن أفراد جنس الطُّلاَّب ، أي : أنَّه لم يَغِبْ أيّ طالب . وهذا هو معنى قولهم :
مِنْ الزائدة تُفِيدُ النَّصَّ على العُمُوم .
الإعراب : ما غابَ مِنْ طَالِبٍ .
ما : حرف نفي مبني على السكون لا محلّ له من الإعراب .
غابَ : فعل ماضٍ مبنيّ على الفتح .
مِنْ : حرف جرًّ زائد مبني على السكون .
طالبٍ : فاعل مرفوع وعلامة رفعه الضمة المقدَّرة منع من ظهورها اشتغال المحلَّ
بحركة حرف الجر الزائد (الكسرة ).
* قد يكون مجرورُ مِنْ فاعلاً ، كما في المثال السابق .
وقد يكون مفعولاً به ، نحو : لا تظلمْ مِن أحدٍ ؛ لأن الأصل : لا تظلمْ أحداً .
وقد يكون مبتدأً ، نحو : هل من سؤالٍ ؟ والأصل : هل سؤالٌ عندكم ؟', 19, 20, 1
from public.rules
where course_name = 'Мединский курс (Том 3)' and lesson_number = '2' and sort_order = 6;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_3.pdf', 'لَدَى
لَدَى : ظرفُ مكانٍ مُعْرَبٌ ، وهو بمعنى ( عِنْدَ ) نحو : وجدتُ القلمَ لَدَى زيدٍ .
تُقْلَب أَلِفُهَا ياءً عند إضافتها إلى الضمير ، نحو : ماذا لَدَيْكَ ؟
قال تعالى : ﴿ وَلَدَيْنَا كِتَابٌ يَنْطِقُ بِالْحَقِّ ﴾ .
إعرابها : لديَّ قَلَمٌ .
لديَّ : ظرف مكان منصوب بفتحة مقدَّرة منع من ظهورها التَّعَذُّر ، وهو مضاف
وياء المتكلَّم في محل جر مضاف إليه ، وشبه الجملة ( لديَّ ) في محل رفع خبر
مقدَّم .
قلمٌ : مبتدأ مُؤَخَّر مرفوع وعلامة رفعة الضمة الظاهرة .', 20, 20, 1
from public.rules
where course_name = 'Мединский курс (Том 3)' and lesson_number = '2' and sort_order = 7;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_3.pdf', 'الْجَمْعُ على صِيغَةِ مُنْتَهَى الْجُمُوعِ
صِيغَةُ مَنْتَهى الجموع لها أوزان كثيرة ، منها: مَفَاعِل ، وفَوَاعِل ، وفَيَاعِل ، وفَعَائِل ؛ ومفاعيل ...إلخ.
ومعنى مُنْتَهى الجموع ، أي : نِهَايَة الْجَمْع . وهذه الصَّيَغ ممنوعة من الصرف .
نحو : مَسَاجِدَ ، وخَوَاِتمَ ، وصَيَارِف ، وصَحَائِفَ ؛ ومصابيح .
* إذا جاء الاسم المنقوص على صيغة مُنتهى الجموع عُومِلَ مُعَامَلة الاسم المنقوص المفرد ،
فَتُحْذَف ياؤُه رفعاً ، وجَرّاً ، ويُنَوَّنُ تنوين عِوَض .
الأمثلة :
للواوِ مَعَانٍ كثيرةٌ : مبتدأ مرفوع وعلامة رفعه الضمة المقدّرة على الياء المحذوفة .
والتنوين عِوَض عن الياء المحذوفة .
اشْتركتُ في نَوَادٍ ثَقَافِيَّةٍ : اسم مجرور بـ ( في ) وعلامة جرَّه الفتحة المقدَّرة على
الياء المحذوفة ، والتنوين لِلْعِوَضِ .
عِشْتُ لياليَ سعيدةً : مفعول به منصوب وعلامة نصبه الفتحة الظاهرة .', 21, 21, 1
from public.rules
where course_name = 'Мединский курс (Том 3)' and lesson_number = '2' and sort_order = 8;

  select count(*) into new_rule_count
  from public.rules
  where course_name = 'Мединский курс (Том 3)' and lesson_number = '2';

  select count(*) into source_count
  from public.rule_sources rs
  join public.rules r on r.id = rs.rule_id
  where r.course_name = 'Мединский курс (Том 3)' and r.lesson_number = '2';

  if new_rule_count <> 8 or source_count <> 8 then
    raise exception 'Book 3 lesson 2 verification failed: rules %, sources %', new_rule_count, source_count;
  end if;
end
